import 'dart:convert';
import 'dart:typed_data';

/// Banner placed at the top of every generated text file.
const generatedNotice =
    'GENERATED by app/tool/brand from brand.yaml. Do not edit; run `make brand` to regenerate.';

/// The files one generator run produces: paths relative to the app folder, in
/// the order they were added.
final class Outputs {
  final Map<String, Uint8List> files = {};

  /// Adds a text file (UTF-8, `\n` line ends, one trailing newline).
  void text(String path, String content) =>
      bytes(path, utf8.encode(content.endsWith('\n') ? content : '$content\n'));

  void bytes(String path, List<int> data) {
    if (files.containsKey(path)) throw StateError('Generated twice: $path');
    files[path] = Uint8List.fromList(data);
  }
}
